// OpenGL straight to the host's (the user allowed it: the game's renderer wants a 3.2 core profile with its
// extensions, which DecompRecomp's own OpenGL-on-Metal does not offer). The table-driven shims are generated by the
// framework's glgen.py; here is what needs a hand: strings and arrays of pointers that live in guest memory, buffer
// mappings (the game gets a copy in its own memory, written back when it unmaps), sync objects, and CGL, whose
// context is a handle of the bridge's (the same one [NSOpenGLContext CGLContextObj] gives the game).
#define GL_SILENCE_DEPRECATION
#include "dr_bridge.h"
#include "dr_objc.h"
#include "rt.h"
#include <stdatomic.h>
#include <OpenGL/OpenGL.h>
#include <OpenGL/gl.h>
#include <OpenGL/glext.h>
#include <OpenGL/gl3.h>
#include <OpenGL/gl3ext.h>
#include <pthread.h>
#include <time.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void aot_lock(void);
void aot_unlock(void);
uint32_t aot_malloc(uint32_t n);
void aot_free(uint32_t p);
dr_objc *dr_objc_actual(void);

#define RET(v) (c->eax = (uint32_t)(v))
#define P(g) ((g) ? G2H(g) : NULL)

// A handle always stands for the same host object, and the game asks for its few GL contexts thousands of times a
// frame (it locks and unlocks its context around every batch): the ones seen are kept, so that looking one up does
// not take the runtime's one lock, which the rendering thread was spending a third of its time waiting for.
static void *host(uint32_t v) {
    if (!v) return NULL;
    static struct { uint32_t v; void *h; } seen[16];
    for (int i = 0; i < 16; i++) {
        uint32_t k = __atomic_load_n(&seen[i].v, __ATOMIC_SEQ_CST);
        if (k == v) { void *h = __atomic_load_n(&seen[i].h, __ATOMIC_SEQ_CST); if (h) return h; }
        if (!k) break;
    }
    aot_lock(); void *h = dr_objc_object_for(dr_objc_actual(), v); aot_unlock();
    if (h) for (int i = 0; i < 16; i++) {
        uint32_t none = 0;
        if (__atomic_compare_exchange_n(&seen[i].v, &none, v, 0, __ATOMIC_SEQ_CST, __ATOMIC_SEQ_CST)) { __atomic_store_n(&seen[i].h, h, __ATOMIC_SEQ_CST); break; }
        if (none == v) break;
    }
    return h;
}
static uint32_t handle(const void *h) {
    if (!h) return 0;
    aot_lock(); uint32_t v = dr_objc_handle_for(dr_objc_actual(), (void *)h); aot_unlock();
    return v;
}
static uint32_t gstr(const char *s) { uint32_t g = aot_malloc((uint32_t)strlen(s) + 1); strcpy((char *)G2H(g), s); return g; }

// ---- tracing (BMAA_TRACE_GL=1: every call by name, and the error the one before it raised) ----
static int tracing = -1;
void gl_trace(const char *name) {
    if (tracing < 0) tracing = getenv("BMAA_TRACE_GL") != NULL;
    if (tracing) {
        GLenum e = CGLGetCurrentContext() ? glGetError() : 0;
        fprintf(stderr, "  [gl] %s%s\n", name, e ? "  (the call before raised an error)" : "");
    }
}
void gl_trace_args(const char *name, CPU *c, int nslots) { (void)name; (void)c; (void)nslots; }

// ---- pointers that are offsets when a buffer is bound ----
static void *maybe(GLenum binding, uint32_t g) {
    GLint b = 0; glGetIntegerv(binding, &b);
    return b ? (void *)(uintptr_t)g : P(g);
}
void *gl_ptr_array(uint32_t g)   { return maybe(GL_ARRAY_BUFFER_BINDING, g); }
void *gl_ptr_element(uint32_t g) { return maybe(GL_ELEMENT_ARRAY_BUFFER_BINDING, g); }
void *gl_ptr_unpack(uint32_t g)  { return maybe(GL_PIXEL_UNPACK_BUFFER_BINDING, g); }
void *gl_ptr_pack(uint32_t g)    { return maybe(GL_PIXEL_PACK_BUFFER_BINDING, g); }

// ---- strings ----
void I__glGetString(CPU *c) {
    static uint32_t cache[16]; static GLenum keys[16];
    GLenum e = ARG(0);
    for (int i = 0; i < 16; i++) if (keys[i] == e && cache[i]) { RET(cache[i]); return; }
    const char *s = (const char *)glGetString(e);
    if (!s) { RET(0); return; }
    if (getenv("BMAA_TRACE_GL")) fprintf(stderr, "  [gl] glGetString(0x%x) = \"%.200s\"\n", e, s);
    for (int i = 0; i < 16; i++) if (!keys[i]) { keys[i] = e; cache[i] = gstr(s); RET(cache[i]); return; }
    RET(gstr(s));
}
void I__glGetStringi(CPU *c) {
    static struct { GLenum e; GLuint i; uint32_t g; } cache[1024]; static int n;
    for (int k = 0; k < n; k++) if (cache[k].e == ARG(0) && cache[k].i == ARG(1)) { RET(cache[k].g); return; }
    const char *s = (const char *)glGetStringi(ARG(0), ARG(1));
    if (!s) { RET(0); return; }
    uint32_t g = gstr(s);
    if (n < 1024) { cache[n].e = ARG(0); cache[n].i = ARG(1); cache[n].g = g; n++; }
    RET(g);
}
// (shader, count, const char **strings, const GLint *lengths): an array of guest pointers
void I__glShaderSource(CPU *c) {
    GLsizei n = (GLsizei)ARG(1);
    const char **strs = calloc(n ? (size_t)n : 1, sizeof *strs);
    for (GLsizei i = 0; i < n; i++) strs[i] = (const char *)G2H(rd32(ARG(2) + 4 * (uint32_t)i));
    glShaderSource(ARG(0), n, strs, ARG(3) ? (const GLint *)G2H(ARG(3)) : NULL);
    free(strs);
}
void I__glTransformFeedbackVaryings(CPU *c) {
    GLsizei n = (GLsizei)ARG(1);
    const char **strs = calloc(n ? (size_t)n : 1, sizeof *strs);
    for (GLsizei i = 0; i < n; i++) strs[i] = (const char *)G2H(rd32(ARG(2) + 4 * (uint32_t)i));
    glTransformFeedbackVaryings(ARG(0), n, strs, ARG(3));
    free(strs);
}

// ---- buffer mappings: a copy in the game's memory, written back ----
typedef struct { GLenum target; GLuint buf; uint32_t shadow; GLintptr off; GLsizeiptr len; int write, read; } Mapping;
static Mapping maps[256];
static pthread_mutex_t maps_mx = PTHREAD_MUTEX_INITIALIZER;
static GLuint bound(GLenum target) {
    GLenum q = target == GL_ARRAY_BUFFER ? GL_ARRAY_BUFFER_BINDING : target == GL_ELEMENT_ARRAY_BUFFER ? GL_ELEMENT_ARRAY_BUFFER_BINDING :
               target == GL_PIXEL_UNPACK_BUFFER ? GL_PIXEL_UNPACK_BUFFER_BINDING : target == GL_PIXEL_PACK_BUFFER ? GL_PIXEL_PACK_BUFFER_BINDING :
               target == GL_UNIFORM_BUFFER ? GL_UNIFORM_BUFFER_BINDING : target == GL_COPY_READ_BUFFER ? GL_COPY_READ_BUFFER :
               target == GL_COPY_WRITE_BUFFER ? GL_COPY_WRITE_BUFFER : target == GL_TRANSFORM_FEEDBACK_BUFFER ? GL_TRANSFORM_FEEDBACK_BUFFER_BINDING :
               target == GL_TEXTURE_BUFFER ? GL_TEXTURE_BUFFER : 0;
    GLint b = 0; if (q) glGetIntegerv(q, &b);
    return (GLuint)b;
}
static uint32_t map_range(GLenum target, GLintptr off, GLsizeiptr len, int read, int write) {
    GLuint buf = bound(target);
    if (!buf || len <= 0) return 0;
    uint32_t shadow = aot_malloc((uint32_t)len);
    if (!shadow) return 0;
    if (read) glGetBufferSubData(target, off, len, G2H(shadow)); else memset(G2H(shadow), 0, (size_t)len);
    pthread_mutex_lock(&maps_mx);
    for (int i = 0; i < 256; i++) if (!maps[i].shadow) {
        maps[i] = (Mapping){ target, buf, shadow, off, len, write, read };
        pthread_mutex_unlock(&maps_mx);
        return shadow;
    }
    pthread_mutex_unlock(&maps_mx);
    fprintf(stderr, "  [gl] too many buffers mapped at once\n");
    aot_free(shadow);
    return 0;
}
static Mapping *mapping(GLenum target) {
    GLuint buf = bound(target);
    for (int i = 0; i < 256; i++) if (maps[i].shadow && maps[i].buf == buf && maps[i].target == target) return &maps[i];
    return NULL;
}
void I__glMapBuffer(CPU *c) {
    GLint size = 0; glGetBufferParameteriv(ARG(0), GL_BUFFER_SIZE, &size);
    RET(map_range(ARG(0), 0, size, ARG(1) != GL_WRITE_ONLY, ARG(1) != GL_READ_ONLY));
}
void I__glMapBufferRange(CPU *c) {
    GLbitfield acc = ARG(3);
    // a write-only mapping that does not promise to overwrite everything still shows the old contents
    int read = (acc & GL_MAP_READ_BIT) || !(acc & (GL_MAP_INVALIDATE_RANGE_BIT | GL_MAP_INVALIDATE_BUFFER_BIT));
    RET(map_range(ARG(0), (GLintptr)(int32_t)ARG(1), (GLsizeiptr)(int32_t)ARG(2), read, (acc & GL_MAP_WRITE_BIT) != 0));
}
// (target, offset within the mapping, length): what the game says it has written so far
void I__glFlushMappedBufferRange(CPU *c) {
    pthread_mutex_lock(&maps_mx); Mapping *m = mapping(ARG(0)); pthread_mutex_unlock(&maps_mx);
    if (m && m->write) glBufferSubData(m->target, m->off + (int32_t)ARG(1), (GLsizeiptr)(int32_t)ARG(2), (uint8_t *)G2H(m->shadow) + (int32_t)ARG(1));
}
void I__glFlushMappedBufferRangeAPPLE(CPU *c) { I__glFlushMappedBufferRange(c); }
void I__glUnmapBuffer(CPU *c) {
    pthread_mutex_lock(&maps_mx); Mapping *m = mapping(ARG(0)); Mapping mm = m ? *m : (Mapping){0}; if (m) m->shadow = 0; pthread_mutex_unlock(&maps_mx);
    if (!mm.shadow) { RET(GL_FALSE); return; }
    if (mm.write) glBufferSubData(mm.target, mm.off, mm.len, G2H(mm.shadow));
    aot_free(mm.shadow);
    RET(GL_TRUE);
}

// ---- sync objects: pointers of the host's, handles for the game ----
void I__glFenceSync(CPU *c) { RET(handle(glFenceSync(ARG(0), ARG(1)))); }
void I__glDeleteSync(CPU *c) { GLsync s = host(ARG(0)); if (s) glDeleteSync(s); }
void I__glClientWaitSync(CPU *c) {
    GLsync s = host(ARG(0));
    uint64_t t = (uint64_t)ARG(2) | ((uint64_t)ARG(3) << 32);
    RET(s ? glClientWaitSync(s, ARG(1), t) : GL_WAIT_FAILED);
}
void I__glTextureBarrierNV(CPU *c) { }   // not in the host's OpenGL: nothing to do when a texture is never both

// ---- plain ones the framework writes by hand for its own game ----
void I__glViewport(CPU *c) { gl_trace("glViewport"); glViewport((GLint)ARG(0), (GLint)ARG(1), (GLsizei)ARG(2), (GLsizei)ARG(3)); }
void I__glScissor(CPU *c)  { gl_trace("glScissor"); glScissor((GLint)ARG(0), (GLint)ARG(1), (GLsizei)ARG(2), (GLsizei)ARG(3)); }
void I__glGetProgramivARB(CPU *c) { glGetProgramivARB(ARG(0), ARG(1), P(ARG(2))); }

// ---- CGL ----
void I__CGLGetCurrentContext(CPU *c) { RET(handle(CGLGetCurrentContext())); }
void I__CGLSetCurrentContext(CPU *c) { RET(CGLSetCurrentContext(host(ARG(0)))); }
void I__CGLLockContext(CPU *c)   { CGLContextObj x = host(ARG(0)); RET(x ? CGLLockContext(x) : kCGLBadContext); }
void I__CGLUnlockContext(CPU *c) { CGLContextObj x = host(ARG(0)); RET(x ? CGLUnlockContext(x) : kCGLBadContext); }
void I__CGLEnable(CPU *c)  { CGLContextObj x = host(ARG(0)); RET(x ? CGLEnable(x, ARG(1)) : kCGLBadContext); }
void I__CGLDisable(CPU *c) { CGLContextObj x = host(ARG(0)); RET(x ? CGLDisable(x, ARG(1)) : kCGLBadContext); }
void I__CGLSetParameter(CPU *c) { CGLContextObj x = host(ARG(0)); RET(x ? CGLSetParameter(x, ARG(1), P(ARG(2))) : kCGLBadContext); }
void I__CGLGetParameter(CPU *c) { CGLContextObj x = host(ARG(0)); RET(x ? CGLGetParameter(x, ARG(1), P(ARG(2))) : kCGLBadContext); }
// BMAA_GL_DUMP=file.ppm: the back buffer as it is about to be shown, written once at frame BMAA_GL_DUMP_FRAME
// (100 by default) and again every 300 frames after: what the game drew, whatever the screen is doing.
static void dump_frame(void) {
    static int frame; static const char *path; static int at = -1;
    if (at < 0) { path = getenv("BMAA_GL_DUMP"); at = getenv("BMAA_GL_DUMP_FRAME") ? atoi(getenv("BMAA_GL_DUMP_FRAME")) : 100; }
    frame++;
    {   // BMAA_GL_FPS=1: frames shown, every five seconds
        static int fps = -1, last; static double t0;
        if (fps < 0) fps = getenv("BMAA_GL_FPS") != NULL;
        if (fps) {
            struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts); double t = ts.tv_sec + ts.tv_nsec / 1e9;
            if (!t0) t0 = t;
            if (t - t0 >= 5) { fprintf(stderr, "  [gl] %.1f frames a second (frame %d)\n", (frame - last) / (t - t0), frame); t0 = t; last = frame; }
        }
    }
    if (!path || frame < at || (frame - at) % 300) return;
    GLint vp[4], fb = 0, rb = 0; glGetIntegerv(GL_VIEWPORT, vp); glGetIntegerv(GL_FRAMEBUFFER_BINDING, &fb); glGetIntegerv(GL_READ_BUFFER, &rb);
    int w = vp[0] + vp[2], h = vp[1] + vp[3];
    if (w <= 0 || h <= 0 || w > 8192 || h > 8192) return;
    unsigned char *px = malloc((size_t)w * h * 3);
    glBindFramebuffer(GL_FRAMEBUFFER, 0); glReadBuffer(GL_BACK);
    glPixelStorei(GL_PACK_ALIGNMENT, 1);
    glReadPixels(0, 0, w, h, GL_RGB, GL_UNSIGNED_BYTE, px);
    glBindFramebuffer(GL_FRAMEBUFFER, (GLuint)fb); glReadBuffer((GLenum)rb);
    FILE *f = fopen(path, "wb");
    if (f) { fprintf(f, "P6 %d %d 255\n", w, h); for (int y = h - 1; y >= 0; y--) fwrite(px + (size_t)y * w * 3, 3, (size_t)w, f); fclose(f); }
    fprintf(stderr, "  [gl] frame %d written to %s (%dx%d, error 0x%x)\n", frame, path, w, h, glGetError());
    free(px);
}
void fps_frame(void);
void I__CGLFlushDrawable(CPU *c) { CGLContextObj x = host(ARG(0)); gl_trace("CGLFlushDrawable"); if (x) { dump_frame(); fps_frame(); } RET(x ? CGLFlushDrawable(x) : kCGLBadContext); }
void I__CGLClearDrawable(CPU *c) { CGLContextObj x = host(ARG(0)); RET(x ? CGLClearDrawable(x) : kCGLBadContext); }
void I__CGLGetShareGroup(CPU *c) { CGLContextObj x = host(ARG(0)); RET(x ? handle(CGLGetShareGroup(x)) : 0); }
void I__CGLQueryRendererInfo(CPU *c) {
    CGLRendererInfoObj r = NULL; GLint n = 0;
    CGLError e = CGLQueryRendererInfo(ARG(0), &r, &n);
    if (ARG(1)) wr32(ARG(1), handle(r));
    if (ARG(2)) wr32(ARG(2), (uint32_t)n);
    RET(e);
}
void I__CGLDescribeRenderer(CPU *c) {
    CGLRendererInfoObj r = host(ARG(0));
    GLint v = 0;
    CGLError e = r ? CGLDescribeRenderer(r, (GLint)ARG(1), ARG(2), &v) : kCGLBadRendererInfo;
    // megabytes of video memory: a 32-bit engine does its sums in a signed 32-bit number of bytes
    if ((ARG(2) == kCGLRPVideoMemoryMegabytes || ARG(2) == kCGLRPTextureMemoryMegabytes) && v > 1536) v = 1536;
    if (ARG(3)) wr32(ARG(3), (uint32_t)v);
    RET(e);
}
void I__CGLDestroyRendererInfo(CPU *c) { CGLRendererInfoObj r = host(ARG(0)); RET(r ? CGLDestroyRendererInfo(r) : kCGLBadRendererInfo); }
